// Turns the attachments (binary data) into batches of up to 5 documents for Nokfi.
const TYPES = ['application/pdf', 'image/jpeg', 'image/png', 'image/webp'];
const docs = [];
for (let i = 0; i < $input.all().length; i++) {
  const item = $input.all()[i];
  for (const [key, bin] of Object.entries(item.binary || {})) {
    if (!TYPES.includes(bin.mimeType)) continue;
    const buffer = await this.helpers.getBinaryDataBuffer(i, key);
    docs.push({ name: bin.fileName || key, mime: bin.mimeType, data: buffer.toString('base64') });
  }
}
const batches = [];
for (let k = 0; k < docs.length; k += 5) batches.push({ json: { files: docs.slice(k, k + 5) } });
return batches;

// One row per invoice, with Nokfi's checks in columns.
const rows = [];
for (const item of $input.all()) {
  for (const inv of item.json.invoices || []) {
    rows.push({ json: {
      file: inv.file_name, issuer: inv.issuer_name, issuer_nif: inv.issuer_nif,
      number: inv.invoice_number, date: inv.invoice_date, due_date: inv.due_date,
      base: inv.base, vat_rate: inv.vat_rate, vat: inv.vat_amount, withholding: inv.irpf_amount, total: inv.total,
      adds_up: inv.checks.totals_ok ? 'yes' : 'NO', nif_valid: inv.checks.nif_valid ? 'yes' : 'NO',
      warnings: (inv.warnings || []).map(w => w.message).join(' · ')
    } });
  }
}
return rows;
